__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"HVORFOR_SMAA_TING",{enumerable:!0,get:function(){return t}}),Object.defineProperty(e,"FELT_FORKLARING",{enumerable:!0,get:function(){return n}}),Object.defineProperty(e,"FIRE_SIDER",{enumerable:!0,get:function(){return o}}),Object.defineProperty(e,"OPFOELGNING_INTRO",{enumerable:!0,get:function(){return l}}),Object.defineProperty(e,"ARRANGEMENT_TYPE_LABEL",{enumerable:!0,get:function(){return s}});const t=["Det, der flytter noget, er sj\xe6ldent stort.","En lille ting, der gentager sig, \xe6ndrer mere end en stor ting, der ikke g\xf8r. Ikke fordi den er lille \u2014 fordi den bliver ved.","Du skal ikke lave dit liv om. Du skal g\xf8re \xe9n ting i dag."],n={serotonin:{kort:"Ro, selvv\xe6rd, m\xe6thed.",hvadVarmerDet:"Lys, n\xe6rv\xe6r, og at flytte blikket v\xe6k fra dig selv.",hvorforDetBetyderNoget:"Feltet med de billigste indgange. Det er som regel her, det er nemmest at begynde."},dopamin:{kort:"Drivkraft. F\xf8lelsen af at gide.",hvadVarmerDet:"Kulde, noget nyt, og pauser fra de hurtige kicks \u2014 ikke flere af dem.",hvorforDetBetyderNoget:"Det varmes af det, der koster lidt. Derfor forsvinder det, n\xe5r alt bliver for let."},oxytocin:{kort:"Tilknytning og tryghed.",hvadVarmerDet:"Ber\xf8ring, kontakt, gener\xf8sitet \u2014 og at v\xe6re i n\xe6rheden af nogen.",hvorforDetBetyderNoget:"St\xf8rst effekt og st\xf8rst modstand. Alt her koster lidt mod, og ingen sensor kan se det. Derfor er det ogs\xe5 det, der lettest forsvinder."},endorfin:{kort:"Udladning og smertelindring.",hvadVarmerDet:"Vedvarende anstrengelse, temperatur, latter og at blive r\xf8rt.",hvorforDetBetyderNoget:"Kr\xe6ver mere end de andre \u2014 og giver mest tilbage."}},o="Fire biologiske systemer, der hver d\xe6kker en side af det at have det godt. Har \xe9t af dem v\xe6ret koldt l\xe6nge, kan man m\xe6rke det \u2014 ogs\xe5 selvom man ikke kan s\xe6tte ord p\xe5 hvad der mangler.",l="Du har brugt appen en uges tid. M\xe5 jeg sp\xf8rge om to ting, s\xe5 forslagene passer bedre?",s={faellesspisning:"f\xe6llesspisning",aaben_kaffe:"\xe5ben kaffe",gaahold:"g\xe5hold",banko:"banko",faelles_madlavning:"f\xe6lles madlavning",haandarbejde:"h\xe5ndarbejde",filmaften:"filmaften"}},350,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"PRIVATLIVSPOLITIK_VERSION",{enumerable:!0,get:function(){return t}}),Object.defineProperty(e,"PRIVATLIVSPOLITIK",{enumerable:!0,get:function(){return n}});const t="2026-09-04",n=[{overskrift:"Dataansvarlig",afsnit:["firklang er lavet af Jameel Hopland som privatperson. Ejerform (om appen p\xe5 et tidspunkt bliver til et selskab) er ikke afgjort endnu, og denne politik opdateres, hvis det \xe6ndrer sig.","Kontakt: jameel@hopland.dk"]},{overskrift:"Der er ingen konto",afsnit:["Du opretter dig ikke, logger dig ikke ind og skriver ikke navn, mail eller telefonnummer ind i appen for at bruge den. Det, appen ved om dig, er det, du selv har skrevet eller trykket p\xe5 din egen telefon."]},{overskrift:"Det appen gemmer p\xe5 din telefon",afsnit:["Alt det her ligger kun i appens eget lager p\xe5 din telefon (localStorage). Det forlader ikke telefonen, medmindre du selv laver en sikkerhedskopi eller siger ja til at dele et kvartalstal.","Dine logninger af, hvad du har lavet, og hvorn\xe5r. Dine hensyn (for eksempel graviditet, hjerte-kar-sygdom eller spiseforstyrrelse), hvis du har sat dem. Dine fravalg, for eksempel om du vil se forslag der koster penge, eller om du vil sk\xe5ne dig for ber\xf8ring.","Tilladelser du har givet, for eksempel om appen m\xe5 foresl\xe5 ting med fremmede, eller om du er under 18. Din WHO-5-tilstand, alts\xe5 om appen lige nu regner dig for et sted der skal g\xe5 stille (den afledte tilstand, ikke selve tallet). Selve WHO-5-scoren gemmes ikke.","Din hjemmeposition, brugt til vejr og dagslys. Den vises aldrig til andre. Dine venner, hvis du har lagt navne og telefonnumre ind under Venner.","Afdelingskoden, hvis du har tastet en kode fra en plakat i din opgang, for at se din boligafdelings arrangementer. Et trivselsb\xe5nd (om dit WHO-5-svar l\xe5 over eller under WHO's egen gr\xe6nse), i den korte periode mellem at du svarer og at du selv trykker ja eller nej til at dele det. Siger du ikke ja, bliver b\xe5ndet aldrig sendt og slettes igen."]},{overskrift:"Netv\xe6rkskald appen laver",afsnit:["Appen er en hjemmeside, du har lagt p\xe5 din startsk\xe6rm (en PWA), og den henter sit indhold over internettet, ligesom enhver anden hjemmeside.","Indholdet i appen (aktiviteter, opskrifter, din boligafdelings arrangementer) hentes fra GitHub Pages og fra hopland.dk. Som ved ethvert bes\xf8g p\xe5 en hjemmeside ser disse to udbydere din IP-adresse og tidspunktet for hvert opslag, i deres egne driftslogs. De ser ikke, hvad du g\xf8r inde i appen, og de f\xe5r ikke din afdelingskode, dine hensyn eller dine logninger.","Supabase kontaktes kun, hvis du selv har sagt s\xe6rskilt ja til at dele et kvartalstal. Bruger du ikke den funktion, taler appen aldrig med Supabase.","Ud over det laver appen ingen netv\xe6rkskald. Der er ingen annoncer, ingen analyse-v\xe6rkt\xf8jer og ingen tredjeparts-sporing."]},{overskrift:"Kvartalstal: det eneste appen kan sende om dig, og kun med dit eget ja",afsnit:["Nogle boligafdelinger bruger firklang som del af en boligsocial indsats. Hvis din afdeling g\xf8r det, kan appen en gang i mellem, efter du har svaret p\xe5 WHO-5, vise dig et kort der sp\xf8rger, om du vil dele \xe9t enkelt tal. Siger du ikke ja, sker der intet. Kortet vises aldrig samme dag som du svarede.","Siger du ja, sendes pr\xe6cis dette, og intet andet: om dit svar l\xe5 over eller under WHO-5's egen gr\xe6nse for lav trivsel (aldrig selve tallet), hvilket kvartal det er, din boligafdelings trivselskode (den samme kode alle i afdelingen bruger, ikke en kode der er unik for dig), og hvilken version af denne politik du s\xe5, da du trykkede ja. Der sendes aldrig et navn, en telefon, en position eller noget andet, der kan pege p\xe5 dig.","Modtageren er Supabase, vores databehandler, som driver den database appen sender til (serveren st\xe5r i Frankfurt, EU). N\xe5r du trykker ja, ser Supabase kort din IP-adresse og tidspunktet for selve opkaldet, i deres egen driftslog. Det er ikke en del af selve tallet, og det gemmes ikke sammen med det.","Databasen gemmer ikke din besvarelse som en r\xe6kke. Den t\xe6ller op i \xe9n t\xe6ller pr. afdeling pr. kvartal og smider din besvarelse v\xe6k med det samme. Det betyder ogs\xe5, at appen bagefter ikke kan finde dit eget tal igen for at vise det til dig, rette det eller slette det for sig selv. Vil du fortryde, skal du g\xf8re det, f\xf8r du trykker ja.","Denne del af appen er slukket, indtil en uafh\xe6ngig databeskyttelsesvurdering (en DPIA) er lavet og accepteret, og indtil det er afklaret, hvem der juridisk st\xe5r som dataansvarlig for den. S\xe5 l\xe6nge den er slukket, kan intet trivselstal sendes, uanset hvad du trykker."]},{overskrift:"Intet sendes uden dit eget tryk",afsnit:["Bortset fra det almindelige indhold der hentes ubetinget, sender appen aldrig noget om dig, uden at du selv har trykket p\xe5 noget, der siger det tydeligt. Der er ingen baggrundsoverf\xf8rsel, ingen automatisk synkronisering og ingen skjult indsamling."]},{overskrift:"Sikkerhedskopi",afsnit:["Du kan lave en sikkerhedskopi af dine data i Indstillinger. Filen er ukrypteret. Den kan indeholde dine hensyn, dine logninger og de navne og telefonnumre, du selv har skrevet ind under Venner. Gemmer du filen i en sky eller sender du den til dig selv, forlader oplysningerne din telefon. Det er dit eget valg, ikke appens.","Afdelingskoden, trivselsb\xe5ndet, din hjemmeposition og dine venner er som udgangspunkt holdt uden for sikkerhedskopien, medmindre du selv v\xe6lger at tage dem med."]},{overskrift:"Slet alle mine data",afsnit:["Under Indstillinger kan du slette alt, appen har gemt om dig, i \xe9t tryk. Det sletter alt p\xe5 din telefon med det samme. Det kan ikke fortrydes. Det sletter ikke en tidligere sikkerhedskopi-fil, du selv har gemt et andet sted, og det kan ikke slette et kvartalstal, du allerede har delt."]},{overskrift:"Dine rettigheder",afsnit:["Fordi det meste af det, appen gemmer, kun ligger p\xe5 din egen telefon, har du hele tiden selv adgang til det, kan selv rette det, og kan slette det med \"Slet alle mine data\". For kvartalstallet g\xe6lder: du kan altid lade v\xe6re med at trykke ja, og du kan ikke bagefter bede om at f\xe5 et allerede sendt tal slettet, fordi det ikke ligger gemt som dit.","Du kan altid skrive til jameel@hopland.dk med sp\xf8rgsm\xe5l om denne politik eller om, hvad appen g\xf8r med det, du taster ind."]},{overskrift:"Klageadgang",afsnit:["Mener du, at dine oplysninger er blevet behandlet forkert, kan du klage til Datatilsynet, Carl Jacobsens Vej 35, 2500 Valby, telefon 33 19 32 00, dt@datatilsynet.dk, datatilsynet.dk."]},{overskrift:"Om retsgrundlaget",afsnit:["Langt det meste af denne politik handler om data, der aldrig forlader din telefon. N\xe5r ingen uden for telefonen indsamler, ser eller behandler de oplysninger, er der efter vores forel\xf8bige vurdering sandsynligvis slet ikke tale om en behandling af personoplysninger, som kr\xe6ver et retsgrundlag fra os som dataansvarlig. Denne vurdering er ved at blive kvalificeret af en ekstern r\xe5dgiver, og formuleringen her rettes til, n\xe5r svaret foreligger.","For den lille del der rent faktisk sendes, kvartalstallet, er retsgrundlaget dit udtrykkelige, s\xe6rskilte samtykke, givet p\xe5 det kort du selv trykker ja til, og som du kan lade v\xe6re med at give."]},{overskrift:"WHO-5",afsnit:["Trivselsm\xe5lingen i appen bygger p\xe5 WHO-5 Trivselsindekset, udviklet af WHO Regionalkontoret for Europa. Brugen af skemaet er ikke-kommerciel."]},{overskrift:"\xc6ndringer",afsnit:["\xc6ndrer vi noget v\xe6sentligt i denne politik, opdaterer vi datoen \xf8verst. Har du sagt ja til at dele et kvartalstal, sendes din politikversion med, s\xe5 det altid kan ses, hvilken udgave af denne tekst du s\xe5, da du sagde ja."]}]},351,[]);
